// Re-implementation of boltons.strutils' pluralize / singularize /
// cardinalize, matching the reference behavior character for character.
//
// Observed algorithm (black-box):
//   1. An empty word is returned unchanged.
//   2. The word is lowercased for lookup and rule application.
//   3. If the lowercased word is in the uninflected set, the ORIGINAL word
//      is returned untouched (case and all).
//   4. Otherwise the plural is computed from the lowercased word: the
//      irregular map first, then suffix rules ([^aeiou]y -> ies,
//      s|ch|sh -> +es, default +s). Note there is no x/z -> es rule:
//      'box' -> 'boxs', 'quiz' -> 'quizs'.
//   5. Case restoration: if the original word isupper() -> plural uppercased;
//      else if it istitle() -> plural title-cased; otherwise the lowercase
//      plural is returned as-is ('WoLf' -> 'wolves', 'iTem' -> 'items').

import { UNINFLECTED, IRREGULAR_PLURALS } from './plural-data.mjs';
import { isUpper, isTitle, title } from './pystr.mjs';

function applyPluralRules(lowered) {
  if (/[^aeiou]y$/.test(lowered)) {
    return lowered.slice(0, -1) + 'ies';
  }
  if (/(?:s|ch|sh)$/.test(lowered)) {
    return lowered + 'es';
  }
  return lowered + 's';
}

export function pluralize(word) {
  if (!word) return word;
  word = String(word);
  const lowered = word.toLowerCase();
  if (UNINFLECTED.has(lowered)) {
    return word;
  }
  const plural = Object.prototype.hasOwnProperty.call(IRREGULAR_PLURALS, lowered)
    ? IRREGULAR_PLURALS[lowered]
    : applyPluralRules(lowered);
  if (isUpper(word)) return plural.toUpperCase();
  if (isTitle(word)) return title(plural);
  return plural;
}

// boltons.strutils.singularize is effectively the identity function: the
// reference returns the word unchanged for every input (even obvious
// plurals like 'knives', 'children' or 'Boxes').
export function singularize(word) {
  return word;
}

// cardinalize(unit_noun, count): singular for count == 1, plural otherwise.
export function cardinalize(unitNoun, count) {
  if (count === 1) {
    return singularize(unitNoun);
  }
  return pluralize(unitNoun);
}

