import { cardinalize } from './pluralize.mjs';

// unit_len(sized_iterable, unit_noun='item'):
//   '<count> <cardinalize(unit_noun, count)>'
export function unitLen(sizedIterable, unitNoun = 'item') {
  const count = sizedIterable.length;
  const unit = cardinalize(unitNoun, count);
  return `${count} ${unit}`;
}

