// Minimal re-implementation of the Python argparse behavior used by the
// original script:
//
//   parser = argparse.ArgumentParser()
//   parser.add_argument('--a', type=str, required=True,
//                       help='Comma-separated items')
//   parser.add_argument('--b', type=str, required=True, help='Unit name')
//   args = parser.parse_args()
//
// Reproduces: long options with separate or '='-joined values, unique-prefix
// abbreviation (argparse's allow_abbrev default), '-h'/'--help', the '--'
// separator, negative-number-looking values, and argparse's usage / error
// text on stderr with exit code 2 (help goes to stdout with exit code 0).

import { basename } from 'node:path';

const OPTIONS = [
  { names: ['-h', '--help'], dest: 'help', takesValue: false },
  { names: ['--a'], dest: 'a', takesValue: true, metavar: 'A', required: true },
  { names: ['--b'], dest: 'b', takesValue: true, metavar: 'B', required: true },
];

function usageLine(prog) {
  return `usage: ${prog} [-h] --a A --b B`;
}

function helpText(prog) {
  return `${usageLine(prog)}

options:
  -h, --help  show this help message and exit
  --a A       Comma-separated items
  --b B       Unit name
`;
}

function errorExit(prog, message) {
  process.stderr.write(`${usageLine(prog)}\n${prog}: error: ${message}\n`);
  process.exit(2);
}

// argparse treats a token as an option string (rather than a value) when it
// starts with '-', is more than one character, does not look like a negative
// number (the parser has no number-like options), and contains no space.
function looksLikeOptionString(token) {
  if (token.length < 2 || token[0] !== '-') return false;
  if (/^-\d+$|^-\d*\.\d+$/.test(token)) return false; // negative number
  if (token.includes(' ')) return false;
  return true;
}

function findLongOption(optString) {
  const exact = OPTIONS.find((o) => o.names.includes(optString));
  if (exact) return { option: exact };
  const matches = OPTIONS.filter((o) =>
    o.names.some((n) => n.startsWith('--') && n.startsWith(optString))
  );
  if (matches.length === 1) return { option: matches[0] };
  if (matches.length > 1) {
    const candidates = matches
      .map((o) => o.names.find((n) => n.startsWith(optString)))
      .join(', ');
    return { ambiguous: candidates };
  }
  return { option: null };
}

export function parseArguments(argv) {
  const prog = basename(process.argv[1] || '');
  const values = {};
  const extras = [];
  let sawDoubleDash = false;

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];

    if (!sawDoubleDash && token === '--') {
      sawDoubleDash = true;
      continue;
    }

    if (!sawDoubleDash && token.startsWith('--')) {
      let optString = token;
      let inlineValue = null;
      const eq = token.indexOf('=');
      if (eq !== -1) {
        optString = token.slice(0, eq);
        inlineValue = token.slice(eq + 1);
      }
      const { option, ambiguous } = findLongOption(optString);
      if (ambiguous) {
        errorExit(prog, `ambiguous option: ${optString} could match ${ambiguous}`);
      }
      if (!option) {
        extras.push(token);
        continue;
      }
      if (!option.takesValue) {
        // -h/--help: print help to stdout and exit 0 immediately, exactly
        // like argparse's help action.
        if (inlineValue !== null) {
          errorExit(prog, `argument ${optString}: ignored explicit argument '${inlineValue}'`);
        }
        process.stdout.write(helpText(prog));
        process.exit(0);
      }
      if (inlineValue !== null) {
        values[option.dest] = inlineValue;
      } else {
        const next = argv[i + 1];
        if (next === undefined || looksLikeOptionString(next)) {
          errorExit(prog, `argument ${optString}: expected one argument`);
        }
        values[option.dest] = next;
        i++;
      }
      continue;
    }

    if (!sawDoubleDash && looksLikeOptionString(token)) {
      if (token === '-h') {
        process.stdout.write(helpText(prog));
        process.exit(0);
      }
      extras.push(token);
      continue;
    }

    // A bare '-', a negative number, anything after '--', or a plain word:
    // this parser has no positionals, so it ends up unrecognized.
    extras.push(token);
  }

  const missing = OPTIONS.filter(
    (o) => o.required && !(o.dest in values)
  ).map((o) => o.names[0]);
  if (missing.length > 0) {
    errorExit(prog, `the following arguments are required: ${missing.join(', ')}`);
  }
  if (extras.length > 0) {
    errorExit(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return values;
}

