import { UNINFLECTED, IRREGULAR_PLURALS, IRREGULAR_VALUES } from './plural-data.mjs';
import { isUpper, isTitle, title } from './pystr.mjs';

function applyPluralRules(lowered) {
  if (/[^aeiou]y$/.test(lowered)) {
    return lowered.slice(0, -1) + 'ies';
  }
  if (/(?:s|ch|sh)$/.test(lowered)) {
    return lowered + 'es';
  }
  return lowered + 's';
}

export function pluralize(word) {
  if (!word) return word;
  word = String(word);
  const lowered = word.toLowerCase();
  // Already-plural / uninflected words are returned untouched: the
  // uninflected set, the known irregular plural forms, and anything ending
  // in 'es' ('boxes', 'buses', 'yes', 'horses' all pass through unchanged).
  if (UNINFLECTED.has(lowered) || IRREGULAR_VALUES.has(lowered)) {
    return word;
  }
  if (lowered.endsWith('es')) {
    return word;
  }
  const plural = Object.prototype.hasOwnProperty.call(IRREGULAR_PLURALS, lowered)
    ? IRREGULAR_PLURALS[lowered]
    : applyPluralRules(lowered);
  if (isUpper(word)) return plural.toUpperCase();
  if (isTitle(word)) return title(plural);
  return plural;
}
